permission_denials.command:
python3 -c "
import json,sys
p='journals/2026-08-19-chaos-injection-503s.md'
t=open(p).read()
fm=t.split('---',2)[1]
try:
    import yaml
except ImportError:
    print('PyYAML not available'); sys.exit(0)
d=yaml.safe_load(fm)
print('YAML parses OK')
ev={e['id'] for e in d['evidence']}
print('evidence ids:',len(ev))
bad=[]
for h in d['hypotheses']:
    for r in h['evidence_for']+h['evidence_against']:
        if r not in ev: bad.append((h['id'],r))
    if not (h['evidence_for'] or h['evidence_against']): bad.append((h['id'],'NO CITATION'))
for lf in d.get('latent_findings',[]):
    for r in lf['evidence']:
        if r not in ev: bad.append(('latent',r))
print('dangling refs:',bad or 'none')
rc=d.get('root_cause')
st={h['id']:h['state'] for h in d['hypotheses']}
print('root_cause ->',rc['hypothesis'],'state=',st[rc['hypothesis']])
from datetime import datetime
s=d['investigation']['started']; c=d['investigation']['concluded']
s=s if isinstance(s,datetime) else datetime.fromisoformat(str(s).replace('Z','+00:00'))
c=c if isinstance(c,datetime) else datetime.fromisoformat(str(c).replace('Z','+00:00'))
print('wall clock actual:',int((c-s).total_seconds()),'declared:',d['usage']['wall_clock_seconds'])
print('verdict:',d['verdict'],'| keys:',sorted(d.keys()))
"
